use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;
        // Only mark items as seen once the digest was actually published;
        // otherwise they should be reconsidered on the next run.
        if published.published {
            for id in published.considered.iter() {
                state_rw::put(id, &published.date);
                recorded += 1;
            }
        }
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
